export type ParsedSubmitCandidateInstruction<
  TProgram extends string = typeof SCOUT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    payer: TAccountMetas[0];
    scout: TAccountMetas[1];
    roleVault: TAccountMetas[2];
    scoutProfile: TAccountMetas[3];
    /**
     * The PDA is unique per (role, candidate): a second submission of the same
     * candidate fails here, so the first scout keeps the credit.
     */
    submission: TAccountMetas[4];
    vaultTokenAccount: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: SubmitCandidateInstructionData;
};

export function parseSubmitCandidateInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSubmitCandidateInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      payer: getNextAccount(),
      scout: getNextAccount(),
      roleVault: getNextAccount(),
      scoutProfile: getNextAccount(),
      submission: getNextAccount(),
      vaultTokenAccount: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getSubmitCandidateInstructionDataDecoder().decode(instruction.data),
  };
}
